// Libraries the shell loads that have no installed type definitions.
declare module 'gi://Soup?version=3.0' {
  const Soup: any;
  export default Soup;
}

declare module 'gi://GWeather' {
  const GWeather: any;
  export default GWeather;
}

declare module 'gi://Gst?version=1.0' {
  const Gst: any;
  export default Gst;
}
